SELECT COUNT(*)
FROM TB_COM_GRP_CD
WHERE GRP_CD = #{grpCd}

SELECT GRP_CD, DTL_CD, DTL_CD_NM, DTL_CD_DESC, SORT_ORD, ATTR_VAL1, ATTR_VAL2, ATTR_VAL3, ATTR_VAL4, ATTR_VAL5, USE_YN, REG_USER_ID, REG_DT, MOD_USER_ID, MOD_DT FROM TB_COM_DTL_CD WHERE GRP_CD = #{grpCd}
AND USE_YN = #{useYn}
ORDER BY SORT_ORD ASC, DTL_CD ASC

SELECT GRP_CD, DTL_CD, DTL_CD_NM, DTL_CD_DESC, SORT_ORD,
       ATTR_VAL1, ATTR_VAL2, ATTR_VAL3, ATTR_VAL4, ATTR_VAL5,
       USE_YN, REG_USER_ID, REG_DT, MOD_USER_ID, MOD_DT
FROM TB_COM_DTL_CD
WHERE GRP_CD = #{grpCd}
  AND DTL_CD = #{dtlCd}

SELECT COUNT(*)
FROM TB_COM_DTL_CD
WHERE GRP_CD = #{grpCd}
  AND DTL_CD = #{dtlCd}

